document.addEventListener('DOMContentLoaded', function() {
  const startBtn = document.getElementById('start-btn');
  const micSelect = document.getElementById('mic-select');
  const dbValue = document.getElementById('db-value');
  const meterFill = document.getElementById('meter-fill');
  const levelIndicator = document.getElementById('level-indicator');
  const statusMessage = document.getElementById('status-message');
  const statusAlert = document.getElementById('status-alert');
  const statCurrent = document.getElementById('stat-current');
  const statAvg = document.getElementById('stat-avg');
  const statPeak = document.getElementById('stat-peak');
  const historyCanvas = document.getElementById('history-canvas');
  const historyCtx = historyCanvas.getContext('2d');
  const resetStatsBtn = document.getElementById('reset-stats-btn');

  let audioContext = null;
  let analyser = null;
  let microphone = null;
  let audioStream = null;
  let isRunning = false;
  let animationId = null;

  let readings = [];
  let peakValue = 0;
  let historyData = [];
  const maxHistoryPoints = 100;

  // Resize canvas
  function resizeCanvas() {
    historyCanvas.width = historyCanvas.offsetWidth;
    historyCanvas.height = historyCanvas.offsetHeight;
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Get audio devices
  async function getAudioDevices() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(track => track.stop());

      const devices = await navigator.mediaDevices.enumerateDevices();
      const audioInputs = devices.filter(d => d.kind === 'audioinput');

      micSelect.innerHTML = '';
      audioInputs.forEach((device, index) => {
        const option = document.createElement('option');
        option.value = device.deviceId;
        option.text = device.label || `Microphone ${index + 1}`;
        micSelect.appendChild(option);
      });
      micSelect.disabled = false;
    } catch (error) {
      updateStatus('danger', 'Microphone access denied. Please allow microphone permissions.');
    }
  }

  // Update status
  function updateStatus(type, message) {
    statusAlert.className = `alert alert-${type}`;
    statusMessage.innerHTML = message;
  }

  // Calculate dB from audio data
  function calculateDb(dataArray) {
    let sum = 0;
    for (let i = 0; i < dataArray.length; i++) {
      const value = (dataArray[i] - 128) / 128;
      sum += value * value;
    }
    const rms = Math.sqrt(sum / dataArray.length);
    const db = 20 * Math.log10(rms + 0.0001);
    // Normalize to 0-100 range (approximate)
    return Math.max(0, Math.min(100, db + 100));
  }

  // Get level description
  function getLevelDescription(db) {
    if (db < 30) return { text: 'Very Quiet', class: 'level-quiet' };
    if (db < 50) return { text: 'Quiet', class: 'level-quiet' };
    if (db < 70) return { text: 'Moderate', class: 'level-moderate' };
    if (db < 85) return { text: 'Loud', class: 'level-loud' };
    return { text: 'Very Loud', class: 'level-very-loud' };
  }

  // Draw history graph
  function drawHistory() {
    historyCtx.fillStyle = '#f8f9fa';
    historyCtx.fillRect(0, 0, historyCanvas.width, historyCanvas.height);

    if (historyData.length < 2) return;

    historyCtx.strokeStyle = '#0055FF';
    historyCtx.lineWidth = 2;
    historyCtx.beginPath();

    const stepX = historyCanvas.width / (maxHistoryPoints - 1);

    for (let i = 0; i < historyData.length; i++) {
      const x = i * stepX;
      const y = historyCanvas.height - (historyData[i] / 100 * historyCanvas.height);

      if (i === 0) {
        historyCtx.moveTo(x, y);
      } else {
        historyCtx.lineTo(x, y);
      }
    }
    historyCtx.stroke();
  }

  // Update meter
  function updateMeter() {
    if (!analyser || !isRunning) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyser.getByteTimeDomainData(dataArray);

    const db = calculateDb(dataArray);
    const dbRounded = Math.round(db);

    // Update display
    dbValue.textContent = dbRounded;
    meterFill.style.height = `${100 - db}%`;

    const level = getLevelDescription(db);
    levelIndicator.textContent = level.text;
    levelIndicator.className = `level-indicator ${level.class}`;

    // Update statistics
    readings.push(db);
    if (readings.length > 1000) readings.shift();

    if (db > peakValue) peakValue = db;

    const avgDb = readings.reduce((a, b) => a + b, 0) / readings.length;

    statCurrent.textContent = `${dbRounded} dB`;
    statAvg.textContent = `${Math.round(avgDb)} dB`;
    statPeak.textContent = `${Math.round(peakValue)} dB`;

    // Update history
    historyData.push(db);
    if (historyData.length > maxHistoryPoints) historyData.shift();
    drawHistory();

    animationId = requestAnimationFrame(updateMeter);
  }

  // Start measuring
  async function startMeasuring() {
    if (isRunning) {
      stopMeasuring();
      return;
    }

    try {
      const deviceId = micSelect.value;
      const constraints = {
        audio: deviceId ? { deviceId: { exact: deviceId } } : true
      };

      audioStream = await navigator.mediaDevices.getUserMedia(constraints);
      audioContext = new (window.AudioContext || window.webkitAudioContext)();
      analyser = audioContext.createAnalyser();
      microphone = audioContext.createMediaStreamSource(audioStream);
      microphone.connect(analyser);
      analyser.fftSize = 2048;

      isRunning = true;
      startBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop Measuring';
      startBtn.classList.remove('btn-primary');
      startBtn.classList.add('btn-danger');
      micSelect.disabled = true;

      updateStatus('success', 'Measuring sound levels... Speak or make sounds to see the levels.');
      updateMeter();
    } catch (error) {
      updateStatus('danger', 'Error accessing microphone: ' + error.message);
    }
  }

  // Stop measuring
  function stopMeasuring() {
    isRunning = false;

    if (animationId) {
      cancelAnimationFrame(animationId);
    }

    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
    }

    if (audioContext) {
      audioContext.close();
    }

    startBtn.innerHTML = '<i class="bi bi-play-fill me-2"></i>Start Measuring';
    startBtn.classList.remove('btn-danger');
    startBtn.classList.add('btn-primary');
    micSelect.disabled = false;

    updateStatus('info', 'Measurement stopped. Click "Start Measuring" to begin again.');
  }

  // Reset statistics
  function resetStats() {
    readings = [];
    peakValue = 0;
    historyData = [];
    statCurrent.textContent = '-- dB';
    statAvg.textContent = '-- dB';
    statPeak.textContent = '-- dB';
    drawHistory();
  }

  // Event listeners
  startBtn.addEventListener('click', startMeasuring);
  resetStatsBtn.addEventListener('click', resetStats);

  // Initialize
  getAudioDevices();
});

