/* sound-level-meter.json — restyled from old .db-display/.meter-container/.level-indicator/.history-canvas block */
.db-display{font-family:'JetBrains Mono',monospace;font-size:5rem;font-weight:700;line-height:1;color:var(--amber);}
.db-unit{font-size:2rem;vertical-align:super;color:var(--ink-2);}
.meter-container{height:300px;border-radius:8px;position:relative;overflow:hidden;background:linear-gradient(to top, var(--success) 0%, var(--success) 33%, var(--amber) 33%, var(--amber) 66%, var(--red) 66%, var(--red) 100%);}
.meter-fill{position:absolute;bottom:0;left:0;right:0;background:var(--panel-2);transition:height .1s ease;}
.meter-scale{position:absolute;right:10px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:space-between;color:var(--bg);font-weight:700;font-size:11px;text-shadow:0 1px 2px rgba(0,0,0,.35);}
/* level-indicator: className is fully replaced by the script on every reading ("level-indicator <level>"),
   so all typography lives on the base class rather than a separate .mono helper class. */
.level-indicator{padding:10px 20px;border-radius:4px;font-weight:700;text-align:center;font-family:'JetBrains Mono',monospace;font-size:13px;}
.level-quiet{background:var(--success);color:var(--bg);}
.level-moderate{background:var(--amber);color:var(--bg);}
.level-loud{background:var(--red);color:var(--bg);opacity:.85;}
.level-very-loud{background:var(--red);color:var(--bg);}
.history-canvas{width:100%;height:150px;background:var(--panel-2);border:1px solid var(--border);border-radius:4px;display:block;}
/* severity-coded reference-table rows, replacing Bootstrap's table-success/table-warning/table-danger */
.table .row-safe{background:rgba(46,125,79,.10);}
.table .row-caution{background:var(--amber-dim);}
.table .row-danger{background:rgba(196,67,46,.10);}
/* #status-alert: the tool script overwrites this element's className to a bare "alert alert-<type>"
   string on every status update, so the structural box styling normally supplied by .status-message
   must live on the id selector to survive those updates. */
#status-alert{padding:.6rem .85rem;margin-bottom:.85rem;border-radius:4px;font-size:13px;border:1px solid var(--border);}
